#!/usr/bin/env bash\nset -e\n\n# Mock rationale: Verify that the Terraform module defines required resources and variables.\n\nMODULE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../src" && pwd)"\n\n# Check for variable definition\nif ! grep -q 'variable "name_prefix"' "$MODULE_DIR/main.tf"; then\n  echo "Missing variable name_prefix"\n  exit 1\nfi\n\n# Check for random_id resource\nif ! grep -q 'resource "random_id" "suffix"' "$MODULE_DIR/main.tf"; then\n  echo "Missing random_id resource"\n  exit 1\nfi\n\n# Check for aws_s3_bucket resource\nif ! grep -q 'resource "aws_s3_bucket" "safehouse"' "$MODULE_DIR/main.tf"; then\n  echo "Missing aws_s3_bucket resource"\n  exit 1\nfi\n\n# Check for output bucket_name\nif ! grep -q 'output "bucket_name"' "$MODULE_DIR/main.tf"; then\n  echo "Missing bucket_name output"\n  exit 1\nfi\n\necho "All checks passed."\n
